import type { LinterContext } from '@teambit/linter';
import type { OxlintNodeOptions } from '@teambit/oxc.linter.oxlint-node';

export function computeOxlintNodeOptions(
  options: OxlintNodeOptions,
  context: LinterContext
): OxlintNodeOptions {
  const fixesFlags: OxlintNodeOptions['fixesFlags'] = {
    ...options.fixesFlags,
  };

  if (context.fix) {
    // `bit lint --fix` uses ESLint-style fix types by default. Oxlint's --fix is
    // the equivalent safe baseline; its more invasive modes are opt-in.
    fixesFlags.all = true;
    if (context.fixTypes?.includes('suggestions')) {
      fixesFlags.suggestions = true;
    }
    if (context.fixTypes?.includes('dangerously')) {
      fixesFlags.dangerously = true;
    }
  }

  return {
    ...options,
    // The Bit adapter consumes structured diagnostics only. A single invocation
    // avoids doing type-aware analysis twice and prevents fix races.
    formats: ['json'],
    fixesFlags,
  };
}
